[{"fieldname": "print_heading_template", "fieldtype": "Custom HTML", "options": "{% if doc.payment_type == "Receive" %}

{# ============================== #}
{#   MACRO NUMERO A LETRAS        #}
{# ============================== #}

{%- macro numero_a_letras(n) -%}
    {%- set unidades = ["", "uno", "dos", "tres", "cuatro", "cinco", "seis", "siete", "ocho", "nueve"] -%}
    {%- set especiales = ["diez", "once", "doce", "trece", "catorce", "quince", "dieciséis", "diecisiete", "dieciocho", "diecinueve"] -%}
    {%- set decenas = ["", "", "veinte", "treinta", "cuarenta", "cincuenta", "sesenta", "setenta", "ochenta", "noventa"] -%}
    {%- set centenas = ["", "ciento", "doscientos", "trescientos", "cuatrocientos", "quinientos", "seiscientos", "setecientos", "ochocientos", "novecientos"] -%}

    {%- set entero = n | int -%}
    {%- set decimal = ((n - entero) * 100) | round | int -%}

    {%- macro convertir(num) -%}
        {%- if num == 0 -%}
            cero
        {%- elif num == 100 -%}
            cien
        {%- else -%}
            {%- set c = (num // 100) % 10 -%}
            {%- set d = (num // 10) % 10 -%}
            {%- set u = num % 10 -%}

            {{ centenas[c] }}
            {%- if d == 1 -%}
                {{ " " ~ especiales[u] }}
            {%- elif d == 2 and u > 0 -%}
                {{ " veinti" ~ unidades[u] }}
            {%- else -%}
                {{ " " ~ decenas[d] }}
                {%- if d > 2 and u > 0 -%}
                    {{ " y " ~ unidades[u] }}
                {%- elif d <= 2 and u > 0 -%}
                    {{ " " ~ unidades[u] }}
                {%- endif -%}
            {%- endif -%}
        {%- endif -%}
    {%- endmacro -%}

    {{ convertir(entero) | trim | capitalize }} con {{ "%02d" % decimal }}/100
{%- endmacro -%}



{# ============================== #}
{#   ESTILOS DEL RECIBO           #}
{# ============================== #}
<style>
@media print {

    @page {
        size: Letter;
        margin: 0.5in;
    }

    .recibo-wrapper {
        height: 5.5in; /* Mitad exacta de página carta */
        overflow: hidden;
        page-break-after: always;
    }

</style>


<style>

   
    .titulo {
        text-align: center;
        font-size: 12px;
        font-weight: bold;
        margin-bottom: 1px;
    }
    .subtitulo {
        text-align: center;
        font-size: 12px;
        margin-bottom: 3px;
    }
    .seccion {
        margin-top: 3px;
        margin-bottom: 1px;
        font-weight: bold;
        border-bottom: 1px solid #ccc;
    }
    table {
        width: 100%;
        border-collapse: collapse;
        margin-top: 1px;
    }
    td, th {
        padding: 5px 7px;
        font-size: 12px;
    }
    .tabla-detalle th, .tabla-detalle td {
        border: 1px solid #ccc;
    }
    .total {
        text-align: right;
        font-weight: bold;
    }
    .nota {
        margin-top: 4px;
        font-size: 12px;
        line-height: 1.0;
    }
    .footer {
        margin-top: 5px;
        font-size: 10px;
        text-align: right;
    }
     .separator {
        border-top: 1px dashed #000;
        margin: 10px 0;
    }
   
</style>



{# ============================== #}
{#   MACRO DEL RECIBO             #}
{# ============================== #}

{% macro recibo() %}
<div class="recibo-container">

    <div class="titulo">ADESCO RESIDENCIAL HACIENDA PASATIEMPO SUR</div>
    <div class="subtitulo">CARRETERA A SANTA ANA, KM 25 1/2</div>

    <table>
        <tr>
            <td><strong>{{ doc.name }}</strong></td>
            <td style="text-align:right;"><strong>Fecha:</strong> {{ frappe.format_date(doc.posting_date) }}</td>
        </tr>
    </table>

    <table>
        <tr>
            <td><strong>Miembro:</strong> {{ doc.party_name }}</td>
        </tr>
        <tr>
            <td>
                <strong>Tipo:</strong> {{ doc.party_type }}
                &nbsp;&nbsp;&nbsp;
                <strong>Método:</strong> {{ doc.mode_of_payment }}
            </td>
        </tr>
        <tr>
            <td><strong>Referencia:</strong> {{ doc.reference_no }}</td>
            
        </tr>
    </table>

    <div class="seccion">Detalle del Pago</div>

    <table class="tabla-detalle">
        <thead>
            <tr>
                <th>Descripción</th>
                <th style="width:55px; text-align:right;">Monto</th>
            </tr>
        </thead>
        <tbody>
            {% for ref in doc.references %}
            <tr>
                <td>{{ ref.reference_name }}</td>
                <td style="text-align:right;">${{ ref.allocated_amount }}</td>
            </tr>
            {% endfor %}
        </tbody>
    </table>

    <table style="margin-top:3px;">
        <tr><td><strong>TOTAL SON:</strong> {{ numero_a_letras(doc.paid_amount) }}</td>
            <td class="total">${{ doc.paid_amount }}</td></tr>
            <td><strong>/:</strong> {{ doc.remarks}}</td>
    </table>

    <div class="nota">
        <strong>Nota:</strong> Transferencia Banco Agricola Cta.Cte. 0051-1003140-6  
        <br>Gracias por su pago.
    </div>

    <div class="footer">
        Usuario: {{ doc.owner }}<br>
        {{ frappe.utils.now_datetime() }}
    </div>

</div>
{% endmacro %}



{# ============================== #}
{#   IMPRIMIR DOS COPIAS          #}
{# ============================== #}

{{ recibo() }}

<div class="separator"></div>

{{ recibo() }}

{% endif %}
